def canSpreadApart(s, k):
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1
    ready = [0] * 26
    for pos in range(len(s)):
        best = -1
        for i in range(26):
            if cnt[i] > 0 and ready[i] <= pos and (best < 0 or cnt[i] > cnt[best]):
                best = i
        if best < 0:
            return False
        cnt[best] -= 1
        ready[best] = pos + k
    return True
